import{_ as t,l,o as e,c as s,v as r,p as d,x as i,d as n,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"WireGuard","description":"","frontmatter":{"title":"WireGuard","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wireguard.md","filePath":"cs/wireguard.md","lastUpdated":1789023840000}'),u={name:"cs/wireguard.md"};function p(_,a,E,m,P,A){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="wireguard" tabindex="-1">WireGuard <a class="header-anchor" href="#wireguard" aria-label="Permalink to &quot;WireGuard&quot;">​</a></h1><div class="epigraph"><p>WireGuard 把隧道收成：Curve25519 静态钥、Noise 握手、ChaCha20-Poly1305、每接口一张密码表。代码面小，是为了让「验过」成为可能，不是为了再发明一种 AES。</p><footer>—— Donenfeld, WireGuard: Next Generation Kernel Network Tunnel；Noise Protocol Framework</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/ipsec-ike">IPsec</a>功能全、配置面大。缺口是<strong>故意缩小的 VPN 合同</strong>：固定套件、静态公钥当身份、内核里短路径。不重写 X25519。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IKE 的算法协商与策略语言易配错。WireGuard：身份=公钥，允许列表=谁能进接口，握手用 Noise（含可选预共享）。缺口是端点 IP 漫游与密钥轮换的简单模型，以及「静态钥长期化」对前向保密的影响（握手仍有临时 DH）。</p><h3 id="不是隐匿工具" tabindex="-1">不是隐匿工具 <a class="header-anchor" href="#不是隐匿工具" aria-label="Permalink to &quot;不是隐匿工具&quot;">​</a></h3><p>默认不是反审查。握手包可被识别。Tor 更后。</p><p><span class="marginnote">Donenfeld 白皮书。Linux 主线 wg。本课不写指纹识别隧道的测量步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 IPsec：无版本降级、无用户空间百万行。指出需要用户空间做分配与编排（wg-quick、控制面）。身份仍要带外分发公钥，TOFU 问题换了层。</p>',12)),(e(),d(h,null,{default:i(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAT%5B%22%E9%9D%99%E6%80%81%20X25519%22%5D%20--%3E%20NOISE%5B%22Noise%20%E6%8F%A1%E6%89%8B%22%5D%0A%20%20NOISE%20--%3E%20KEYS%5B%22%E4%BC%9A%E8%AF%9D%20AEAD%20%E9%94%AE%22%5D%0A%20%20ALLOW%5B%22allowed%20IPs%22%5D%20--%3E%20POL%5B%22%E5%85%A5%E7%AB%99%E7%AD%96%E7%95%A5%22%5D%0A%20%20KEYS%20--%3E%20TUN%5B%22%E9%9A%A7%E9%81%93%E5%8C%85%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>小 TCB 降低实现漏洞密度，不降低密钥分发与端点信任问题。下一课把 VPN 对照零信任：隧道把人放进网，不等于应用该信这个人的每一次请求。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Noise 图案全表抄写。VPN 对零信任下一课改假设：网络位置 ≠ 授权。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IPsec 全功能；WireGuard 固定套件与小实现。</li><li>静态公钥身份 + 临时握手键。</li><li>允许列表是策略，不是密码分析。</li><li>下一课：VPN 对零信任。</li><li>出处：Donenfeld, WireGuard；Noise Protocol Framework；RFC 7748。</li></ul>',8))])}const N=t(u,[["render",p]]);export{T as __pageData,N as default};
